import { test, expect } from '@playwright/test';

test.describe('Print Filtered Table View', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the table view page
    await page.goto('http://localhost:3000/table');

    // Wait for the table to load
    await page.waitForSelector('table');
  });

  test('should filter table and print filtered results', async ({ page, context }) => {
    // Find and interact with filter input
    const filterInput = page.getByLabel('Filter');
    await filterInput.fill('John');

    // Wait for table to update with filtered results
    await page.waitForTimeout(500);

    // Verify filtered results are displayed
    const filteredRows = page.getByRole('row');
    const rowCount = await filteredRows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify the filtered content contains the search term
    const tableContent = await page.getByRole('table').textContent();
    expect(tableContent).toContain('John');

    // Click print button
    const printButton = page.getByRole('button', { name: /print/i });
    await printButton.click();

    // Wait for print dialog to appear
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).toBeVisible();

    // Verify print preview shows filtered data
    const printContent = await page.getByRole('document').textContent();
    expect(printContent).toContain('John');
  });

  test('should apply multiple filters and print results', async ({ page }) => {
    // Apply first filter
    const statusFilter = page.getByLabel('Status');
    await statusFilter.selectOption('Active');

    // Apply second filter
    const departmentFilter = page.getByLabel('Department');
    await departmentFilter.selectOption('Engineering');

    // Wait for table to update
    await page.waitForTimeout(500);

    // Verify multiple filters are applied
    const tableRows = page.getByRole('row');
    const rowCount = await tableRows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify filtered results
    const tableContent = await page.getByRole('table').textContent();
    expect(tableContent).toContain('Active');
    expect(tableContent).toContain('Engineering');

    // Open print dialog
    const printButton = page.getByRole('button', { name: /print/i });
    await printButton.click();

    // Verify print dialog is visible
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).toBeVisible();

    // Verify print preview contains filtered data
    const printPreview = page.getByRole('document');
    const printText = await printPreview.textContent();
    expect(printText).toContain('Active');
    expect(printText).toContain('Engineering');
  });

  test('should clear filters and print full table', async ({ page }) => {
    // Apply a filter
    const filterInput = page.getByLabel('Filter');
    await filterInput.fill('Test');

    // Wait for filter to apply
    await page.waitForTimeout(500);

    // Verify filter is applied
    let tableContent = await page.getByRole('table').textContent();
    expect(tableContent).toContain('Test');

    // Clear filter
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();

    // Wait for table to update
    await page.waitForTimeout(500);

    // Verify filter is cleared
    tableContent = await page.getByRole('table').textContent();
    expect(tableContent).not.toContain('Test');

    // Print full table
    const printButton = page.getByRole('button', { name: /print/i });
    await printButton.click();

    // Verify print dialog appears
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).toBeVisible();
  });

  test('should maintain filter state when opening print preview', async ({ page }) => {
    // Apply filter
    const filterInput = page.getByLabel('Filter');
    await filterInput.fill('Alice');

    // Wait for filter to apply
    await page.waitForTimeout(500);

    // Get initial filtered row count
    const initialRows = page.getByRole('row');
    const initialCount = await initialRows.count();

    // Open print dialog
    const printButton = page.getByRole('button', { name: /print/i });
    await printButton.click();

    // Verify print dialog is visible
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).toBeVisible();

    // Close print dialog
    const closeButton = page.getByRole('button', { name: /close|cancel/i }).first();
    await closeButton.click();

    // Verify filter is still applied after closing print dialog
    const filterValue = await filterInput.inputValue();
    expect(filterValue).toBe('Alice');

    // Verify row count is still the same
    const finalRows = page.getByRole('row');
    const finalCount = await finalRows.count();
    expect(finalCount).toBe(initialCount);
  });
});
